function resource(path){if(!path||/^(?:[a-z]+:|\/|\\)/i.test(path)||path.split(/[\\/]/).includes('..'))return null;const base=path.split(/[?#]/)[0],suffix=path.slice(base.length),e=window.RC4_RESOURCE_MAP?.[base];return e?{...e,url:e.url+suffix}:{kind:'unavailable'};}
function link(path,label){const r=resource(path);if(!r)return '';const installed=r.kind==='core'||r.kind==='original'&&(r.install_path?window.KQ_ORIGINAL_UPDATES?.files?.[r.install_path]===r.sha256:window.RC4_ORIGINALS?.installed)||r.kind==='archive'&&window.RC4_ARCHIVE?.installed;return installed?'<a href="'+h(r.url)+'" target="_blank" rel="noopener">'+h(label)+'</a>':r.kind==='archive'?'':btn(label,'resource-help',r.package?'original-pack:'+r.package:r.install_path?'original-update':r.kind);}
function originalLinks(p){return p?(p.source_note?'<p class="source-kind-note">'+h(p.source_note)+'</p>':'')+'<div class="detail-actions">'+p.source_files.map(s=>link(s.path,s.link_label||'查看原卷与解析')).join(' ')+'</div>':'';}
function show(content,title='原题与答案'){if($('reader').open)detailStack.push({html:$('detail').innerHTML,title:$('readerLocation').textContent,scroll:$('reader').scrollTop,focusIndex:[...$('detail').querySelectorAll(focusable)].indexOf(document.activeElement)});else{lastFocus=document.activeElement;detailStack=[];}$('detail').innerHTML=content;$('readerLocation').textContent=title;$('readerBack').textContent=detailStack.length?'返回上一详情':'返回查询';if(!$('reader').open)$('reader').showModal();$('reader').scrollTop=0;$('detail').focus({preventScroll:true});}
function backReader(){if(!detailStack.length){closeReader();return;}const s=detailStack.pop();$('detail').innerHTML=s.html;$('readerLocation').textContent=s.title;$('readerBack').textContent=detailStack.length?'返回上一详情':'返回查询';const target=$('detail').querySelectorAll(focusable)[s.focusIndex];if(target)target.focus({preventScroll:true});else $('detail').focus({preventScroll:true});$('reader').scrollTop=s.scroll;}
function keyboardBack(){
 if($('reader').open){backReader();return true;}
 const picker=$('schoolPicker');if(picker?.open){picker.open=false;picker.querySelector('summary').focus({preventScroll:true});return true;}
 const active=document.activeElement;if(active?.matches('select'))return false;
 if(KQKeyboard.editing(active)){active.blur();return true;}
 if($('moreFilters').open&&!$('moreFilters').hidden){$('moreFilters').open=false;$('moreFilters').querySelector('summary').focus({preventScroll:true});return true;}
 if(drill){returnFromDrill();return true;}
 if(queryTrail.length){restoreQueryFrame(queryTrail.pop());return true;}
 return false;
}
